// Data shapes shared across the app (mirror the future backend DTOs).

export type Role = "admin" | "instructor" | "student" | "parent";
export type Language = "en" | "ar";

/** Text stored in every supported language. */
export type Localized = Record<Language, string>;

export interface User {
  id: string;
  role: Role;
  name: string;
  email: string;
  password: string;
  phone: string;
  phoneVerified: boolean;
  /** True for accounts generated by the admin until the user picks a password. */
  mustChangePassword: boolean;
  /** Parent accounts only. */
  childIds?: string[];
}

export interface Course {
  id: string;
  title: Localized;
  schedule: Localized;
  instructorId: string;
  studentIds: string[];
  feeEgp: number;
  installmentCount: number;
}

export type ContentType = "lesson" | "video" | "file";

export interface ContentItem {
  id: string;
  courseId: string;
  type: ContentType;
  title: Localized;
  body: Localized;
  publishedAt: string;
}

export type AssessmentKind = "assignment" | "quiz";

export interface Assessment {
  id: string;
  courseId: string;
  kind: AssessmentKind;
  title: Localized;
  description: Localized;
  dueAt: string;
  maxScore: number;
}

export interface Submission {
  id: string;
  assessmentId: string;
  studentId: string;
  /** Missing for in-class quizzes that only carry a score. */
  text?: string;
  submittedAt?: string;
  score?: number;
  feedback?: string;
  gradedAt?: string;
}

export interface TimelineEvent {
  id: string;
  courseId: string;
  date: string;
  title: Localized;
  done: boolean;
}

export type AttendanceStatus = "present" | "absent" | "late";

export interface AttendanceRecord {
  id: string;
  courseId: string;
  studentId: string;
  date: string;
  status: AttendanceStatus;
}

export type PaymentMethod = "card" | "instapay" | "cash";

export interface Installment {
  id: string;
  courseId: string;
  studentId: string;
  number: number;
  amountEgp: number;
  dueDate: string;
  method?: PaymentMethod;
  /** Card last digits, InstaPay reference or cash voucher. */
  reference?: string;
  paidAt?: string;
}

export interface Thread {
  id: string;
  participantIds: string[];
  courseId: string;
  /** The student the conversation is about. */
  studentId: string;
}

export interface Message {
  id: string;
  threadId: string;
  senderId: string;
  text: string;
  sentAt: string;
}

export interface AppData {
  users: User[];
  courses: Course[];
  content: ContentItem[];
  assessments: Assessment[];
  submissions: Submission[];
  timeline: TimelineEvent[];
  attendance: AttendanceRecord[];
  installments: Installment[];
  threads: Thread[];
  messages: Message[];
}
